  const fires = bot.findBlocks({
    matching: b => b && (b.name === 'fire' || b.name === 'soul_fire'),
    maxDistance: 6,
    count: 8
  });
  for (const fp of fires) {
    try {
      const b = bot.blockAt(fp);
      if (b && (b.name === 'fire' || b.name === 'soul_fire')) {
        console.log(`Extinguishing fire at ${lib.fmt(fp)}...`);
        await bot.dig(b);
      }
    } catch (e) {}
  }
}

