  if (bot.entity.position.distanceTo(target) < 2.5) continue;

  // Active mob defense
  const piglin = bot.nearestEntity(e => (e.name === 'piglin' || e.name === 'piglin_brute') && e.position.distanceTo(bot.entity.position) <= 4.0);
