      lastRods = curRods;
      console.log(`*** BLAZE ROD ACQUIRED! Count = ${curRods} ***`);
    }

    if (curRods >= targetRods) {
      bot.chat(`gamma: MILESTONE 8 COMPLETE! Reached ${curRods} Blaze Rods!`);
      break;
    }

    await sleep(100);
  }

  try { await lib.pickup(4.0); } catch (e) {}
}

