// 1. Direct Nether Portal warp (no autoload closures)
async function enterNetherPortalDirect() {
  if (bot.game.dimension === 'the_nether') return;

  const target = new Vec3(299.5, 73.0, -53.5);
  console.log('Stepping directly into portal center (299.5, 73.0, -53.5)...');
  await bot.lookAt(target, true);
  bot.setControlState('forward', true);
  if (bot.entity.position.y < 72.8) bot.setControlState('jump', true);
  await sleep(1000);
  bot.setControlState('jump', false);
  bot.setControlState('forward', false);
  bot.clearControlStates();

  console.log('Standing motionless inside portal block. Awaiting dimension warp...');
  const warpStart = Date.now();
  while (bot.game.dimension !== 'the_nether' && Date.now() - warpStart < 20000 && !isCancelled()) {
    const cur = bot.entity.position;
    // Keep centered in portal block
    if (Math.abs(cur.x - 299.5) > 0.4 || Math.abs(cur.z - (-53.5)) > 0.4) {
      await bot.lookAt(target, true);
      bot.setControlState('forward', true);
      await sleep(150);
      bot.setControlState('forward', false);
    }
    await sleep(200);
  }

  if (bot.game.dimension === 'the_nether') {
    console.log('WARP SUCCESS! Inside the_nether at:', lib.fmt(bot.entity.position));
    // Step forward out of portal
    await bot.lookAt(new Vec3(46.0, 65.0, -7.0), true);
    bot.setControlState('forward', true);
    await sleep(1200);
    bot.setControlState('forward', false);
    bot.clearControlStates();
  }
}

