      bot.setControlState('forward', false);
    }

    try { await lib.pickup(3.5); } catch (e) {}

    // Terrain safety check: ensure player stayed on high ridge
    if (bot.entity.position.y < 60) {
      out.log(`CRITICAL: Player fell below y=60! Current y=${bot.entity.position.y}. Aborting march.`);
      break;
    }

    if (bot.health <= 8) {
      out.log(`Health low (${bot.health}) during march at WP ${i + 1}, holding in cover.`);
      break;
    }
  }
  return { dimension: bot.game.dimension, pos: bot.entity.position, hp: bot.health, rods: lib.count('blaze_rod') };
};

// Safe Pillbox Blaze farming (stays in cover, retreats 2 blocks to z=-184 when healing)
globalThis.farmBlazeRodsAtPillbox = async function(targetRods = 8, durationMs = 120000, isCancel = () => false, out = console) {
  bot.pathfinder.stop();
  bot.pathfinder.setGoal(null);
  bot.clearControlStates();
  try { await lib.equipArmor(); } catch (e) {}
  try { await lib.equipWeapon(); } catch (e) {}

  const pillboxPos = new Vec3(37, 66, -186);
  if (bot.entity.position.distanceTo(pillboxPos) > 12) {
    out.log(`farmBlazeRodsAtPillbox: Not at Pillbox! Current pos: ${lib.fmt(bot.entity.position)}`);
    return { error: 'Not at pillbox', pos: bot.entity.position, rods: lib.count('blaze_rod') };
  }

  // Ensure gamma steps precisely into the pillbox firing position
  try {
    await lib.goTo(37.0, 66, -186, 1.0, { dig: false, timeoutMs: 4000 });
  } catch (e) {}

  const start = Date.now();
  let lastRods = lib.count('blaze_rod');
  let lastAttack = 0;
  let killed = 0;

  while (!isCancel() && Date.now() - start < durationMs) {
    // If health drops below 8, step back 2 blocks around corner to z=-184 to break line-of-sight
    if (bot.health < 8) {
      out.log(`HP low (${bot.health.toFixed(1)}), stepping behind wall to (37, 66, -184) for cover...`);
      try { await lib.goTo(37, 66, -184, 1.0, { dig: false, timeoutMs: 3000 }); } catch (e) {}
      await sleep(4000);
      try { await lib.goTo(37, 66, -186, 1.0, { dig: false, timeoutMs: 3000 }); } catch (e) {}
      continue;
    }
    if (bot.food < 16) {
      try { await lib.eat(); } catch (e) {}
    }

    const blazes = Object.values(bot.entities)
      .filter(e => e.name === 'blaze' && e.isValid && (e.health === undefined || e.health > 0))
      .sort((a, b) => bot.entity.position.distanceTo(a.position) - bot.entity.position.distanceTo(b.position));

    const target = blazes[0];
    if (target) {
      const dist = bot.entity.position.distanceTo(target.position);
      if (dist <= 4.8 && Date.now() - lastAttack > 625) {
        await bot.lookAt(target.position.offset(0, (target.height || 1.8) * 0.7, 0), true);
        bot.attack(target);
        lastAttack = Date.now();
        if (target.health !== undefined && target.health <= 0) {
          killed++;
          out.log(`Blaze eliminated! Total kills: ${killed}`);
        }
      }
    }

    // Safe pickup: vacuum dropped Blaze Rods
    if (bot.entity.position.x >= 35.5 && Math.random() < 0.3) {
      try { await lib.pickup(3.5); } catch (e) {}
    }

    const curRods = lib.count('blaze_rod');
    if (curRods > lastRods) {
      bot.chat(`${bot.username}: Harvested Blaze Rod! Total: ${curRods}/${targetRods}`);
      lastRods = curRods;
    }
    if (curRods >= targetRods) break;
    await sleep(150);
  }

  try { if (bot.entity.position.x >= 35.5) await lib.pickup(3.5); } catch (e) {}
  return { killed, rods: lib.count('blaze_rod'), hp: bot.health, pos: bot.entity.position };
};

